#ifndef CZ_AK_H
#define CZ_AK_H

#include <CZ/Core/Cuarzo.h>
#include <CZ/skia/core/SkFontMgr.h>
#include <filesystem>

#define AK_MAX_BUFFER_AGE 3

/**
 * @defgroup AKCore Core
 * @brief Core classes
 */

/**
 * @defgroup AKEffects Effects
 * @brief Background effects that can be attached to nodes.
 */

/**
 * @defgroup AKEvents Events
 * @brief Events generated by scenes and dispatched to nodes.
 */

/**
 * @defgroup AKInput Input
 * @brief Input state and focus tracking.
 */
namespace CZ
{
    class AKApp;
    class AKObject;

    class AKTheme;
    class AKChanges;
    class AKBackgroundDamageTracker;

    class AKScene;  /* Renders a root AKNode into an AKTarget */
    class AKTarget;
    class AKTarget; /* An AKScene render destination */
    class AKLayout; /* Yoga layout of an AKNode */

    /*********** CORE NODE TYPES ***********/

    class AKNode;       /* Base class for nodes */
    class AKContainer;  /* Container for other nodes. Doesn't produce any output on its own */
    class AKRenderable; /* A node that draws directly into an AKTarget */
    class AKBakeable;   /* A node that draws into its own buffer, which is then blitted into an AKTarget */
    class AKSubScene;   /* A node whose children are drawn into its own buffer and then rendered into an AKTarget */

    class AKSolidColor;
    class AKRoundSolidColor;
    class AKPath;
    class AKImage;
    class AKImageFrame;
    class AKThreePatch;
    class AKNinePatch;
    class AKFontIcon;
    class AKTextCaret;
    class AKText;
    class AKCoreTextEditor;
    class AKRoundContainer;
    class AKButton;
    class AKButtonGroup;
    class AKTextField;
    class AKWindowButton;
    class AKWindowButtonGroup;
    class AKScroll;
    class AKScrollBar;

    class AKIconFont;

    /************ EFFECTS ************/

    class AKRoundCornersEffect;
    class AKBackgroundEffect;
    class AKBackgroundBoxShadowEffect;
    class AKBackgroundImageShadowEffect;
    class AKBackgroundBlurEffect;
    class AKEdgeShadow;

    /************ INPUT *************/

    class AKKeyboard;
    class AKPointer;

    /************ EVENTS *************/

    class AKRenderEvent;
    class AKBakeEvent;
    class AKSceneChangedEvent;
    class AKVibrancyEvent;

    /************ MARCO *************/
    class MSurface;

    /**
     * @brief Returns the active theme, creating the default one if none has been set.
     * @ingroup AKCore
     */
    AKTheme *theme() noexcept;

    /**
     * @brief Replaces the active theme.
     *
     * Pass a subclassed AKTheme to customize the look of built-in components,
     * or `nullptr` to restore the default theme (created lazily by theme()).
     *
     * @ingroup AKCore
     */
    void setTheme(AKTheme *theme) noexcept;

    /**
     * @brief Returns the shared Skia font manager (see AKApp::fontManager()).
     * @ingroup AKCore
     */
    sk_sp<SkFontMgr> akFontManager() noexcept;

    /**
     * @brief Returns the pointer state of the current AKApp (see AKApp::pointer()).
     * @ingroup AKInput
     */
    AKPointer &akPointer() noexcept;

    /**
     * @brief Returns the keyboard state of the current AKApp (see AKApp::keyboard()).
     * @ingroup AKInput
     */
    AKKeyboard &akKeyboard() noexcept;

    /**
     * @brief Directory containing Kay's bundled assets (e.g. icon fonts).
     * @ingroup AKCore
     */
    const std::filesystem::path &AKAssetsDir() noexcept;

    /**
     * @brief Directory containing Kay's bundled fonts.
     * @ingroup AKCore
     */
    const std::filesystem::path &AKFontsDir() noexcept;

};

#define AK_IRECT_INF SkIRect::MakeLTRB(-2147483, -2147483, 2147483, 2147483)

#endif // CZ_AK_H
